export function cloneParameterList(source: TransmissionShaftPage1ParameterItem[]): TransmissionShaftPage1ParameterItem[] {
  return source.map(item => ({
    ...item,
    tableMap: item.tableMap
      ? {
          ...item.tableMap,
          rowData: item.tableMap.rowData?.map(row => ({ ...row })),
        }
      : item.tableMap,
  }));
}

export function getTableRows(list: TransmissionShaftPage1ParameterItem[], index: number) {
  return list[index]?.tableMap?.rowData ?? [];
}

export function setTableRows(list: TransmissionShaftPage1ParameterItem[], index: number, rows: TransmissionTableRow[]) {
  const table = list[index]?.tableMap;
  if (!table) return;
  table.rowData = rows;
  table.rowNums = rows.length;
}
